/bin/bash -lc "cat <<'EOF' > app/lib/analytics.ts
export type PageView = {
  path: string;
  userAgent: string;
  timestamp: string;
};

export async function logPageView(view: PageView) {
  const endpoint = process.env.ANALYTICS_URL;
  if ("'!endpoint) {
    console.info('"'[analytics] Page view', view);
    return;
  }

  try {
    const response = await fetch(endpoint, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
      },
      body: JSON.stringify(view),
      cache: 'no-store',
    });

    if ("'!response.ok) {
      console.warn(
        `[analytics] request failed: ${response.status} ${response.statusText}`
      );
    }
  } catch (error) {
    console.error('"'[analytics] request error', error);
  }
}
EOF"
